		\def\vo{node[circle, color=black, fill=white, inner sep=2pt, minimum size = 17pt, draw]{}}
\begin{tikzpicture}[scale=2]
\foreach \x in {0,...,5}{
	\coordinate (a\x) at (\x*60:1);
}
\foreach \x in {0,...,4}{
	\foreach \y in {\x,...,5}{
		\draw[thick] (a\x) -- (a\y);
	}
	\draw (a\x) \vo;
}
\draw (a5) \vo;
\end{tikzpicture}

END_LATEX_IMAGE

